// AI-assisted: written with help from Claude (Anthropic). See README, "Use of AI tools".
//
// SIMULATED DATA. Every reading produced here is generated by code. None of it
// comes from real astronauts or real devices. Crew names are fictional.

import type { CrewMember, DayRecord, IndicatorId, MissionProfile, ScenarioId } from "../../lib/types";

const DAYS = 30;
export const MISSION_DAY = 142;

/** Small seeded random number generator, so the demo looks the same on every load. */
function rng(seed: number) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const round = (v: number, d: number) => Number(v.toFixed(d));

interface Seed {
  id: string;
  name: string;
  role: string;
  seed: number;
  hr: number;
  bp: number;
  mass: number;
}

const SEEDS: Seed[] = [
  { id: "c1", name: "Aiko Tanaka", role: "Flight engineer", seed: 11, hr: 64, bp: 114, mass: 61.5 },
  { id: "c2", name: "Luis Ortega", role: "Commander", seed: 23, hr: 68, bp: 121, mass: 78.2 },
  { id: "c3", name: "Sana Malik", role: "Mission specialist", seed: 37, hr: 60, bp: 109, mass: 66.0 },
];

function buildMember(s: Seed, profile: MissionProfile): CrewMember {
  const r = rng(s.seed);
  const between = (lo: number, hi: number) => lo + r() * (hi - lo);
  const history: DayRecord[] = [];

  for (let i = 0; i < DAYS; i++) {
    const values: Record<IndicatorId, number> = {
      hr: round(s.hr + between(-4, 4), 0),
      spo2: round(between(96, 99), 0),
      temp: round(between(36.4, 37.0), 1),
      bp: round(s.bp + between(-5, 5), 0),
      glucose: round(between(80, 95), 0),
      sleep: round(between(7.0, 8.2), 1),
      mood: r() < 0.7 ? 4 : 5,
      radiation: round(profile.radLimit * between(0.45, 0.65), 2),
      mass: round(s.mass - i * 0.02 + between(-0.15, 0.15), 1),
    };
    history.push({
      day: MISSION_DAY - (DAYS - 1) + i,
      values,
      exerciseMin: r() < 0.85 ? 120 : round(between(60, 100), 0),
    });
  }
  return { id: s.id, name: s.name, role: s.role, baselineMass: s.mass, history };
}

/** Change the most recent days of one crew member to show a health event. */
function applyScenario(m: CrewMember, scenario: ScenarioId, profile: MissionProfile) {
  const h = m.history;
  const last = (n: number) => h[h.length - 1 - n].values;

  switch (scenario) {
    case "fever":
      last(1).temp = 37.8;
      last(0).temp = 38.7;
      last(0).hr = 108;
      break;
    case "sleep":
      last(3).sleep = 5.8;
      last(2).sleep = 5.4;
      last(1).sleep = 5.6;
      last(0).sleep = 5.2;
      last(1).mood = 3;
      last(0).mood = 3;
      break;
    case "cardiac":
      last(0).hr = 128;
      last(0).bp = 186;
      last(0).spo2 = 91;
      break;
    case "isolation":
      last(2).mood = 2;
      last(1).mood = 2;
      last(0).mood = 2;
      last(1).sleep = 6.4;
      last(0).sleep = 6.2;
      break;
    case "storm":
      last(1).radiation = round(profile.radLimit * 0.9, 2);
      last(0).radiation = round(profile.radLimit * 1.35, 2);
      break;
    case "nominal":
      break;
  }
}

/** What the astronaut entered today. It replaces the simulated values for the latest day. */
export interface TodayInput {
  mood: number | null;
  values: Partial<Record<IndicatorId, number>>;
  extraExercise: number;
}

export function buildCrew(profile: MissionProfile, scenario: ScenarioId, today: TodayInput): CrewMember[] {
  const crew = SEEDS.map((s) => buildMember(s, profile));
  applyScenario(crew[0], scenario, profile);
  const latest = crew[0].history[crew[0].history.length - 1];
  Object.assign(latest.values, today.values);
  if (today.mood !== null) latest.values.mood = today.mood;
  latest.exerciseMin += today.extraExercise;
  return crew;
}

export const SCENARIOS: { id: ScenarioId; label: string }[] = [
  { id: "nominal", label: "Normal day" },
  { id: "fever", label: "Fever" },
  { id: "sleep", label: "Sleep debt" },
  { id: "cardiac", label: "Cardiac event" },
  { id: "isolation", label: "Low mood" },
  { id: "storm", label: "Solar storm" },
];
